package com.danawa.io

/**
 * Mutable byte buffer with offset and limit tracking
 */
class BytesBuffer : Cloneable {

    /** The contents of the BytesRef. Should never be null. */
    @JvmField
    var bytes: ByteArray = ByteArray(0)

    /** Offset of first valid byte. */
    @JvmField
    var offset: Int = 0

    /** limit of used bytes. */
    @JvmField
    var limit: Int = 0

    constructor()

    constructor(size: Int) {
        this.bytes = ByteArray(size)
        clear()
    }

    constructor(buffer: ByteArray) {
        this.bytes = buffer
        clear()
    }

    constructor(buffer: ByteArray, limit: Int) {
        this.bytes = buffer
        this.limit = limit
    }

    constructor(buffer: ByteArray, offset: Int, limit: Int) {
        this.bytes = buffer
        this.offset = offset
        this.limit = limit
    }

    fun init(buffer: ByteArray, offset: Int, limit: Int) {
        this.bytes = buffer
        this.offset = offset
        this.limit = limit
    }

    fun clear() {
        offset = 0
        limit = bytes.size
    }

    fun size(): Int = bytes.size

    fun flip(): BytesBuffer {
        limit = offset
        offset = 0
        return this
    }

    // 현재위치로부터 offset만큼 떨어진 위치의 byte를 리턴해준다.
    // read하지 않고 값을 확인하고 싶을때 사용.
    operator fun get(i: Int): Byte = bytes[offset + i]

    fun array(): ByteArray = bytes

    fun pos(): Int = offset

    fun limit(): Int = limit

    fun pos(pos: Int) {
        this.offset = pos
    }

    fun skip(n: Int) {
        this.offset += n
    }

    fun limit(limit: Int) {
        this.limit = limit
    }

    fun length(): Int = limit - offset

    fun remaining(): Int = limit - offset

    fun readByte(): Byte = bytes[offset++]

    fun read(): Int = bytes[offset++].toInt() and 0xFF

    fun write(b: Int) {
        bytes[offset++] = b.toByte()
    }

    fun write(src: ByteArray, srcPos: Int, srcLen: Int) {
        System.arraycopy(src, srcPos, bytes, offset, srcLen)
        offset += srcLen
    }

    override fun toString(): String {
        return buildString {
            for (i in offset until limit) {
                append(bytes[i])
                append(" ")
            }
        }
    }

    fun toAlphaString(): String {
        return buildString {
            for (i in offset until limit) {
                append(bytes[i].toInt().toChar())
            }
        }
    }

    override fun equals(other: Any?): Boolean {
        if (other !is BytesBuffer) return false
        if (length() != other.length()) return false
        for (i in 0 until limit - offset) {
            if (bytes[offset + i] != other.bytes[other.offset + i]) {
                return false
            }
        }
        return true
    }

    override fun hashCode(): Int {
        var result = 1
        for (i in offset until limit) {
            result = 31 * result + bytes[i]
        }
        return result
    }

    public override fun clone(): BytesBuffer = BytesBuffer(bytes, offset, limit)

    companion object {
        @JvmStatic
        fun compareBuffer(buf1: BytesBuffer, buf2: BytesBuffer): Int {
            val len1 = buf1.length()
            val len2 = buf2.length()
            val len = minOf(len1, len2)
            for (i in 0 until len) {
                if (buf1[i] != buf2[i]) {
                    return buf1[i] - buf2[i]
                }
            }
            return len1 - len2
        }
    }
}

