    22→
    23→/**
    24→ * Abstract base class for performing write operations of Lucene's low-level data types.
    25→ *
    26→ * DataOutput may only be used from one thread, because it is not thread safe
    27→ * (it keeps internal state like file position).
    28→ */
    29→abstract class DataOutput : OutputStream() {
    30→
    31→    private var copyBuffer: ByteArray? = null
    32→
    33→    open fun seekPositionSupported(): Boolean = false
    34→
    35→    @Throws(IOException::class)
    36→    open fun position(): Long {
    37→        throw UnsupportedOperationException()
    38→    }
    39→
    40→    @Throws(IOException::class)
    41→    open fun seek(position: Long) {
    42→        throw UnsupportedOperationException()
    43→    }
    44→
    45→    @Throws(IOException::class)
    46→    abstract fun reset()
    47→
    48→    /**
    49→     * Writes a single byte.
    50→     */
    51→    @Throws(IOException::class)
    52→    abstract fun writeByte(b: Byte)
    53→
    54→    @Throws(IOException::class)
    55→    fun writeByte(b: Int) {
    56→        writeByte(b.toByte())
    57→    }
    58→
    59→    @Throws(IOException::class)
    60→    override fun write(b: Int) {
    61→        writeByte(b.toByte())
    62→    }
    63→
    64→    @Throws(IOException::class)
    65→    fun writeBytes(b: ByteArray) {
    66→        writeBytes(b, b.size)
    67→    }
    68→
    69→    /**
    70→     * Writes an array of bytes.
    71→     */
    72→    @Throws(IOException::class)
    73→    fun writeBytes(b: ByteArray, length: Int) {
    74→        writeBytes(b, 0, length)
    75→    }
    76→
    77→    /**
    78→     * Writes an array of bytes.
    79→     */
    80→    @Throws(IOException::class)
    81→    abstract fun writeBytes(b: ByteArray, offset: Int, length: Int)
    82→
    83→    @Throws(IOException::class)
    84→    fun writeBytes(dst: BytesBuffer) {
    85→        writeBytes(dst.array(), dst.pos(), dst.length())
    86→    }
    87→
    88→    /**
    89→     * Writes an int as four bytes.
    90→     */
    91→    @Throws(IOException::class)
    92→    fun writeInt(i: Int) {
    93→        writeByte((i shr 24).toByte())
    94→        writeByte((i shr 16).toByte())
    95→        writeByte((i shr 8).toByte())
    96→        writeByte(i.toByte())
    97→    }
    98→
    99→    /**
   100→     * Writes a short as two bytes.
   101→     */
   102→    @Throws(IOException::class)
   103→    fun writeShort(i: Short) {
   104→        writeByte((i.toInt() shr 8).toByte())
   105→        writeByte(i.toByte())
   106→    }
   107→
   108→    @Throws(IOException::class)
   109→    fun writeVInt(value: Int) {
   110→        var i = value
   111→        while ((i and 0x7F.inv()) != 0) {
   112→            writeByte(((i and 0x7F) or 0x80).toByte())
   113→            i = i ushr 7
   114→        }
   115→        writeByte(i.toByte())
   116→    }
   117→
   118→    /**
   119→     * Writes a long as eight bytes.
   120→     */
   121→    @Throws(IOException::class)
   122→    fun writeLong(i: Long) {
   123→        writeInt((i shr 32).toInt())
   124→        writeInt(i.toInt())
   125→    }
   126→
   127→    /**
   128→     * Writes a long in a variable-length format.
   129→     */
   130→    @Throws(IOException::class)
   131→    fun writeVLong(value: Long) {
   132→        var i = value
   133→        assert(i >= 0L)
   134→        while ((i and 0x7FL.inv()) != 0L) {
   135→            writeByte(((i and 0x7FL) or 0x80L).toByte())
   136→            i = i ushr 7
   137→        }
   138→        writeByte(i.toByte())
   139→    }
   140→
   141→    /** Copy numBytes bytes from input to ourself. */
   142→    @Throws(IOException::class)
   143→    fun copyBytes(input: DataInput, numBytes: Long) {
   144→        assert(numBytes >= 0) { "numBytes=$numBytes" }
   145→        var left = numBytes
   146→        if (copyBuffer == null) {
   147→            copyBuffer = ByteArray(COPY_BUFFER_SIZE)
   148→        }
   149→        while (left > 0) {
   150→            val toCopy = if (left > COPY_BUFFER_SIZE) COPY_BUFFER_SIZE else left.toInt()
