package com.danawa.io

import java.io.IOException
import java.io.OutputStream
import java.util.*

/**
 * Abstract base class for performing write operations of Lucene's low-level data types.
 *
 * DataOutput may only be used from one thread, because it is not thread safe
 * (it keeps internal state like file position).
 */
abstract class DataOutput : OutputStream() {

    private var copyBuffer: ByteArray? = null

    open fun seekPositionSupported(): Boolean = false

    @Throws(IOException::class)
    open fun position(): Long {
        throw UnsupportedOperationException()
    }

    @Throws(IOException::class)
    open fun seek(position: Long) {
        throw UnsupportedOperationException()
    }

    @Throws(IOException::class)
    abstract fun reset()

    /**
     * Writes a single byte.
     */
    @Throws(IOException::class)
    abstract fun writeByte(b: Byte)

    @Throws(IOException::class)
    fun writeByte(b: Int) {
        writeByte(b.toByte())
    }

    @Throws(IOException::class)
    override fun write(b: Int) {
        writeByte(b.toByte())
    }

    @Throws(IOException::class)
    fun writeBytes(b: ByteArray) {
        writeBytes(b, b.size)
    }

    /**
     * Writes an array of bytes.
     */
    @Throws(IOException::class)
    fun writeBytes(b: ByteArray, length: Int) {
        writeBytes(b, 0, length)
    }

    /**
     * Writes an array of bytes.
     */
    @Throws(IOException::class)
    abstract fun writeBytes(b: ByteArray, offset: Int, length: Int)

    @Throws(IOException::class)
    fun writeBytes(dst: BytesBuffer) {
        writeBytes(dst.array(), dst.pos(), dst.length())
    }

    /**
     * Writes an int as four bytes.
     */
    @Throws(IOException::class)
    fun writeInt(i: Int) {
        writeByte((i shr 24).toByte())
        writeByte((i shr 16).toByte())
        writeByte((i shr 8).toByte())
        writeByte(i.toByte())
    }

    /**
     * Writes a short as two bytes.
     */
    @Throws(IOException::class)
    fun writeShort(i: Short) {
        writeByte((i.toInt() shr 8).toByte())
        writeByte(i.toByte())
    }

    @Throws(IOException::class)
    fun writeVInt(value: Int) {
        var i = value
        while ((i and 0x7F.inv()) != 0) {
            writeByte(((i and 0x7F) or 0x80).toByte())
            i = i ushr 7
        }
        writeByte(i.toByte())
    }

    /**
     * Writes a long as eight bytes.
     */
    @Throws(IOException::class)
    fun writeLong(i: Long) {
        writeInt((i shr 32).toInt())
        writeInt(i.toInt())
    }

    /**
     * Writes a long in a variable-length format.
     */
    @Throws(IOException::class)
    fun writeVLong(value: Long) {
        var i = value
        assert(i >= 0L)
        while ((i and 0x7FL.inv()) != 0L) {
            writeByte(((i and 0x7FL) or 0x80L).toByte())
            i = i ushr 7
        }
        writeByte(i.toByte())
    }

    /** Copy numBytes bytes from input to ourself. */
    @Throws(IOException::class)
    fun copyBytes(input: DataInput, numBytes: Long) {
        assert(numBytes >= 0) { "numBytes=$numBytes" }
        var left = numBytes
        if (copyBuffer == null) {
            copyBuffer = ByteArray(COPY_BUFFER_SIZE)
        }
        while (left > 0) {
            val toCopy = if (left > COPY_BUFFER_SIZE) COPY_BUFFER_SIZE else left.toInt()
            input.readBytes(copyBuffer!!, 0, toCopy)
            writeBytes(copyBuffer!!, 0, toCopy)
            left -= toCopy
        }
    }

    /**
     * Writes a String map.
     */
    @Throws(IOException::class)
    fun writeStringStringMap(map: Map<String, String>?) {
        if (map == null) {
            writeInt(0)
        } else {
            writeInt(map.size)
            for ((key, value) in map) {
                writeString(key)
                writeString(value)
            }
        }
    }

    /**
     * Writes a String set.
     */
    @Throws(IOException::class)
    fun writeStringSet(set: Set<String>?) {
        if (set == null) {
            writeInt(0)
        } else {
            writeInt(set.size)
            for (value in set) {
                writeString(value)
            }
        }
    }

    @Throws(IOException::class)
    fun writeUTF8String(str: String) {
        val charCount = str.length
        writeVInt(charCount)
        for (i in 0 until charCount) {
            val c = str[i].code
            when {
                c <= 0x007F -> writeByte(c.toByte())
                c > 0x07FF -> {
                    writeByte((0xE0 or ((c shr 12) and 0x0F)).toByte())
                    writeByte((0x80 or ((c shr 6) and 0x3F)).toByte())
                    writeByte((0x80 or (c and 0x3F)).toByte())
                }
                else -> {
                    writeByte((0xC0 or ((c shr 6) and 0x1F)).toByte())
                    writeByte((0x80 or (c and 0x3F)).toByte())
                }
            }
        }
    }

    @Throws(IOException::class)
    fun writeAString(str: String?) {
        val s = str ?: ""
        writeAString(s.toCharArray(), 0, s.length)
    }

    // 2byte로 기록한다.
    @Throws(IOException::class)
    fun writeString(str: String?) {
        val s = str ?: ""
        writeUString(s.toCharArray(), 0, s.length)
    }

    @Throws(IOException::class)
    fun writeFloat(v: Float) {
        writeInt(v.toBits())
    }

    @Throws(IOException::class)
    fun writeDouble(v: Double) {
        writeLong(v.toBits())
    }

    @Throws(IOException::class)
    fun writeBoolean(b: Boolean) {
        writeByte(if (b) ONE else ZERO)
    }

    @JvmOverloads
    @Throws(IOException::class)
    fun writeAChar(v: Int, upperCase: Boolean = false) {
        var char = v
        if (upperCase && char in 97..122) {
            char -= 32
        }
        writeByte(char.toByte())
    }

    @JvmOverloads
    @Throws(IOException::class)
    fun writeUChar(v: Int, upperCase: Boolean = false) {
        var char = v
        if (upperCase && char in 97..122) {
            char -= 32
        }
        writeShort(char.toShort())
    }

    @Throws(IOException::class)
    fun writeAString(v: CharArray, start: Int, length: Int) {
        writeVInt(length)
        writeAChars(v, start, length)
    }

    @Throws(IOException::class)
    fun writeUString(v: CharArray, start: Int, length: Int) {
        writeVInt(length * 2)
        writeUChars(v, start, length)
    }

    @JvmOverloads
    @Throws(IOException::class)
    fun writeAChars(v: CharArray, start: Int, length: Int, upperCase: Boolean = false) {
        if (length == 0) return
        var newLength = length
        if (v.isNotEmpty()) {
            if (start >= v.size) {
                throw IOException("start position exceeds array length. start=$start, array.length=${v.size}")
            }
            if (start + length > v.size) {
                newLength = v.size - start
            }
            for (i in 0 until newLength) {
                writeAChar(v[start + i].code, upperCase)
            }
        } else {
            newLength = 0
        }
        // 나머지 0으로 기록
        for (i in 0 until length - newLength) {
            writeAChar(0)
        }
    }

    @JvmOverloads
    @Throws(IOException::class)
    fun writeUChars(v: CharArray, start: Int, length: Int, upperCase: Boolean = false) {
        if (length == 0) return
        var newLength = length
        if (v.isNotEmpty()) {
            if (start >= v.size) {
                throw IOException("start position exceeds array length. start=$start, array.length=${v.size}")
            }
            if (start + length > v.size) {
                newLength = v.size - start
            }
            for (i in 0 until newLength) {
                writeUChar(v[start + i].code, upperCase)
            }
        } else {
            newLength = 0
        }
        // 나머지 0으로 기록
        for (i in 0 until length - newLength) {
            writeUChar(0)
        }
    }

    @Throws(IOException::class)
    fun writeStringArray(array: Array<String>) {
        writeVInt(array.size)
        for (s in array) {
            writeString(s)
        }
    }

    /**
     * Writes a string array, for nullable string, writes it as 0 (empty string).
     */
    @Throws(IOException::class)
    fun writeStringArrayNullable(array: Array<String>?) {
        if (array == null) {
            writeVInt(0)
        } else {
            writeVInt(array.size)
            for (s in array) {
                writeString(s)
            }
        }
    }

    @Throws(IOException::class)
    fun writeMap(map: Map<String, Any?>) {
        writeGenericValue(map)
    }

    @Throws(IOException::class)
    fun writeGenericValue(value: Any?) {
        if (value == null) {
            writeByte((-1).toByte())
            return
        }
        val type = value::class.java
        when {
            type == String::class.java -> {
                writeByte(0.toByte())
                writeString(value as String)
            }
            type == Integer::class.java || type == Int::class.java -> {
                writeByte(1.toByte())
                writeInt(value as Int)
            }
            type == java.lang.Long::class.java || type == Long::class.java -> {
                writeByte(2.toByte())
                writeLong(value as Long)
            }
            type == java.lang.Float::class.java || type == Float::class.java -> {
                writeByte(3.toByte())
                writeFloat(value as Float)
            }
            type == java.lang.Double::class.java || type == Double::class.java -> {
                writeByte(4.toByte())
                writeDouble(value as Double)
            }
            type == java.lang.Boolean::class.java || type == Boolean::class.java -> {
                writeByte(5.toByte())
                writeBoolean(value as Boolean)
            }
            type == ByteArray::class.java -> {
                writeByte(6.toByte())
                val bytes = value as ByteArray
                writeVInt(bytes.size)
                writeBytes(bytes)
            }
            value is List<*> -> {
                writeByte(7.toByte())
                val list = value as List<*>
                writeVInt(list.size)
                for (o in list) {
                    writeGenericValue(o)
                }
            }
            value is Array<*> -> {
                writeByte(8.toByte())
                val array = value as Array<*>
                writeVInt(array.size)
                for (o in array) {
                    writeGenericValue(o)
                }
            }
            value is Map<*, *> -> {
                if (value is LinkedHashMap<*, *>) {
                    writeByte(9.toByte())
                } else {
                    writeByte(10.toByte())
                }
                @Suppress("UNCHECKED_CAST")
                val map = value as Map<String, Any?>
                writeVInt(map.size)
                for ((key, v) in map) {
                    writeString(key)
                    writeGenericValue(v)
                }
            }
            type == java.lang.Byte::class.java || type == Byte::class.java -> {
                writeByte(11.toByte())
                writeByte(value as Byte)
            }
            type == Date::class.java -> {
                writeByte(12.toByte())
                writeLong((value as Date).time)
            }
            value is BytesBuffer -> {
                writeByte(14.toByte())
                writeVInt(value.length())
                writeBytes(value)
            }
            type == java.lang.Short::class.java || type == Short::class.java -> {
                writeByte(16.toByte())
                writeShort(value as Short)
            }
            else -> throw IOException("Can't write type [$type]")
        }
    }

    companion object {
        private const val ZERO: Byte = 0
        private const val ONE: Byte = 1
        private const val COPY_BUFFER_SIZE = 16384
    }
}

