package com.danawa.io

import java.io.EOFException
import java.io.IOException
import java.io.InputStream

/**
 * A DataInput wrapping a plain InputStream.
 */
class InputStreamDataInput(private val inputStream: InputStream) : DataInput() {

    @Throws(IOException::class)
    override fun readByte(): Byte {
        val v = inputStream.read()
        if (v == -1) throw EOFException()
        return v.toByte()
    }

    @Throws(IOException::class)
    override fun readBytes(b: ByteArray, offset: Int, len: Int) {
        var remaining = len
        var off = offset
        while (remaining > 0) {
            val cnt = inputStream.read(b, off, remaining)
            if (cnt < 0) {
                // Partially read the input, but no more data available in the stream.
                throw EOFException()
            }
            remaining -= cnt
            off += cnt
        }
