package com.danawa.io

import java.lang.ref.SoftReference

/**
 * Thread-local cached char array for UTF-8 string reading
 */
object CachedCharArray {

    private class Entry {
        var chars = CharArray(80)
    }

    private val cache = ThreadLocal<SoftReference<Entry>>()

    private fun instance(): Entry {
        val ref = cache.get()
        var entry = ref?.get()
        if (entry == null) {
            entry = Entry()
            cache.set(SoftReference(entry))
        }
        return entry
    }

    @JvmStatic
    fun clear() {
        cache.remove()
    }

    @JvmStatic
    fun getCharArray(size: Int): CharArray {
        val entry = instance()
        if (entry.chars.size < size) {
            entry.chars = CharArray(size)
        }
        return entry.chars
    }
}

